# -*- coding: utf-8 -*-
# Новые задачи 9 класса (квадратичная функция, системы, прогрессии, вероятность, статистика) для навыков с < 3 подходящими задачами, 26.09.
from sympy import *
from itertools import product
x, y, z = symbols("x y z")
R = Rational
G = []
def T(skill, diff, atype, q, k, ds, check, vals=None):
    G.append(dict(skill=skill, diff=diff, atype=atype, q=q, k=k, ds=ds, check=check, vals=vals))
vy = lambda f: f.subs(x, -f.coeff(x, 1) / (2 * f.coeff(x, 2)))

# S04_02 ордината вершины
T("G9_S04_02", "A", "exact_number", r"Найдите ординату вершины параболы $y = x^{2} - 4x + 3$.", r"$-1$",
  [(r"$2$", "Ученик нашёл абсциссу вершины x₀ = 2 и остановился."), (r"$3$", "Ученик взял свободный член c вместо значения функции в вершине."),
   (r"$15$", "Ученик ошибся в знаке абсциссы: подставил x = −2.")], lambda: vy(x**2 - 4 * x + 3) == -1)
T("G9_S04_02", "B", "exact_number", r"Найдите ординату вершины параболы $y = -2x^{2} + 8x - 5$.", r"$3$",
  [(r"$2$", "Ученик нашёл абсциссу вершины x₀ = 2 и остановился."), (r"$-5$", "Ученик взял свободный член c вместо значения функции в вершине."),
   (r"$-29$", "Ученик ошибся в знаке абсциссы: подставил x = −2.")], lambda: vy(-2 * x**2 + 8 * x - 5) == 3)
T("G9_S04_02", "C", "exact_number", r"Найдите наименьшее значение функции $y = 3x^{2} + 6x + 5$.", r"$2$",
  [(r"$-1$", "Ученик указал абсциссу вершины вместо значения функции."), (r"$5$", "Ученик взял значение функции при x = 0."),
   (r"$14$", "Ученик ошибся в знаке абсциссы вершины: подставил x = 1.")], lambda: vy(3 * x**2 + 6 * x + 5) == 2)
# S05_04 свойства по графику
T("G9_S05_04", "B", "text", r"Ветви параболы $y = ax^{2} + bx + c$ направлены вниз, а её вершина — точка $(2; 5)$. Какое утверждение верно?",
  r"$a < 0$, наибольшее значение функции равно $5$",
  [(r"$a > 0$, наименьшее значение функции равно $5$", "Ученик перепутал направление ветвей со знаком a: ветви вниз при a < 0."),
   (r"$a < 0$, наибольшее значение функции равно $2$", "Ученик принял абсциссу вершины за значение функции."),
   (r"$a < 0$, наименьшее значение функции равно $5$", "Ученик не учёл, что при ветвях вниз в вершине достигается наибольшее значение.")],
  lambda: maximum(-(x - 2)**2 + 5, x) == 5)
# S06_02 решение по графику
T("G9_S06_02", "A", "inequality", r"Парабола $y = x^{2} - 5x + 6$ пересекает ось $Ox$ в точках $x = 2$ и $x = 3$. При каких $x$ функция принимает положительные значения?",
  r"$x < 2$ или $x > 3$", [(r"$2 < x < 3$", "Ученик выбрал промежуток между корнями, где парабола с ветвями вверх лежит ниже оси Ox."),
                          (r"$x > 3$", "Ученик потерял левый промежуток."), (r"$x < 2$", "Ученик потерял правый промежуток.")],
  lambda: solve_univariate_inequality(x**2 - 5 * x + 6 > 0, x, relational=False) == Union(Interval.open(-oo, 2), Interval.open(3, oo)))
T("G9_S06_02", "B", "inequality", r"Парабола $y = -x^{2} + 4$ пересекает ось $Ox$ в точках $x = -2$ и $x = 2$. При каких $x$ функция принимает отрицательные значения?",
  r"$x < -2$ или $x > 2$", [(r"$-2 < x < 2$", "Ученик не учёл, что ветви параболы направлены вниз: между корнями функция положительна."),
                           (r"$x > 2$", "Ученик потерял левый промежуток."), (r"$x < -2$", "Ученик потерял правый промежуток.")],
  lambda: solve_univariate_inequality(-x**2 + 4 < 0, x, relational=False) == Union(Interval.open(-oo, -2), Interval.open(2, oo)))
# S14_04 система с тремя переменными
T("G9_S14_04", "B", "text", r"Решите систему уравнений $$\begin{cases} x + y + z = 6, \\ x - y = 2, \\ y + z = 4. \end{cases}$$",
  r"$(2; 0; 4)$", [(r"$(3; 1; 2)$", "Ученик подобрал тройку, удовлетворяющую только первым двум уравнениям."),
                  (r"$(4; 2; 0)$", "Ученик подобрал тройку, удовлетворяющую только первым двум уравнениям: y + z = 2 ≠ 4."),
                  (r"$(2; 0; 2)$", "Ученик ошибся при нахождении z: из y + z = 4 при y = 0 следует z = 4.")],
  lambda: solve([x + y + z - 6, x - y - 2, y + z - 4], [x, y, z]) == {x: 2, y: 0, z: 4})
# S30_05 текстовая задача на сумму АП
T("G9_S30_05", "B", "exact_number", r"В первый день выложили $10$ кирпичей, а в каждый следующий — на $5$ кирпичей больше, чем в предыдущий. Сколько кирпичей выложили за $6$ дней?",
  r"$135$", [(r"$35$", "Ученик нашёл число кирпичей, выложенных только в шестой день."), (r"$210$", "Ученик умножил число кирпичей шестого дня на число дней."),
             (r"$60$", "Ученик не учёл ежедневное увеличение и умножил 10 на 6.")],
  lambda: sum(10 + 5 * i for i in range(6)) == 135)
# S33_05 прикладная задача на бесконечно убывающую ГП
T("G9_S33_05", "C", "exact_number", r"Мяч падает с высоты $10$ м и после каждого удара о землю поднимается на высоту, равную $0{,}6$ предыдущей. Какой путь пройдёт мяч до остановки?",
  r"$40$ м", [(r"$25$ м", "Ученик нашёл сумму 10/(1 − 0,6), не учтя, что каждую высоту подъёма мяч проходит дважды (вверх и вниз)."),
              (r"$50$ м", "Ученик удвоил весь путь, включая первое падение, которое проходится один раз."),
              (r"$15$ м", "Ученик нашёл только сумму высот подъёма 6/(1 − 0,6).")],
  lambda: 10 + 2 * R(6) / (1 - R(6, 10)) == 40)
T("G9_S33_05", "B", "exact_number", r"Сторона первого квадрата равна $4$ см, а сторона каждого следующего квадрата вдвое меньше стороны предыдущего. Найдите сумму площадей всех квадратов (в см$^{2}$).",
  r"$21\dfrac{1}{3}$", [(r"$8$", "Ученик нашёл сумму сторон, а не площадей."), (r"$32$", "Ученик взял знаменатель прогрессии площадей 1/2 вместо 1/4."),
                       (r"$16$", "Ученик учёл только площадь первого квадрата.")],
  lambda: R(16) / (1 - R(1, 4)) == R(64, 3), vals=[R(64, 3), 8, 32, 16])
# S34_01 достоверное событие
T("G9_S34_01", "A", "text", r"Бросают игральный кубик. Какое из событий является достоверным?", "выпадет число очков, меньшее $7$",
  [("выпадет $6$ очков", "Ученик выбрал случайное событие: оно может и не произойти."), ("выпадет $7$ очков", "Ученик выбрал невозможное событие."),
   ("выпадет чётное число очков", "Ученик выбрал случайное событие: может выпасть нечётное число.")],
  lambda: all(v < 7 for v in range(1, 7)))
T("G9_S34_01", "A", "text", r"Из коробки, в которой лежат только красные шары, вынимают один шар. Каким является событие «вынутый шар — красный»?", "достоверным",
  [("невозможным", "Ученик перепутал достоверное событие с невозможным."), ("случайным", "Ученик не учёл, что других шаров в коробке нет."),
   ("противоположным", "Ученик назвал вид события, который определяется только по отношению к другому событию.")], lambda: True)
T("G9_S34_01", "A", "exact_number", r"Чему равна вероятность достоверного события?", r"$1$",
  [(r"$0$", "Ученик перепутал достоверное событие с невозможным."), (r"$0{,}5$", "Ученик считал, что любое событие происходит с вероятностью 1/2."),
   (r"$100$", "Ученик записал 100 %, забыв, что вероятность выражается числом от 0 до 1.")], lambda: True)
# S34_04 противоположное событие
T("G9_S34_04", "A", "text", r"При бросании игрального кубика событие $A$ — «выпало чётное число очков». Какое событие противоположно событию $A$?", "выпало нечётное число очков",
  [("выпало $1$ очко", "Ученик выбрал только один из исходов противоположного события."), ("выпало число очков, большее $3$", "Ученик выбрал событие, которое может произойти одновременно с A."),
   ("выпало $6$ очков", "Ученик выбрал частный случай самого события A.")], lambda: {1, 3, 5} == set(range(1, 7)) - {2, 4, 6})
T("G9_S34_04", "A", "exact_number", r"Вероятность события $A$ равна $0{,}3$. Найдите вероятность события, противоположного $A$.", r"$0{,}7$",
  [(r"$0{,}3$", "Ученик решил, что противоположные события равновероятны."), (r"$-0{,}3$", "Ученик поставил знак минус вместо вычитания из 1."),
   (r"$1{,}3$", "Ученик прибавил вероятность к 1 вместо вычитания.")], lambda: 1 - R(3, 10) == R(7, 10))
# S35_02 монета
T("G9_S35_02", "A", "exact_number", r"Монету бросают один раз. Какова вероятность выпадения «орла»?", r"$\dfrac{1}{2}$",
  [(r"$1$", "Ученик считал выпадение «орла» достоверным событием."), (r"$0$", "Ученик считал выпадение «орла» невозможным событием."),
   (r"$\dfrac{1}{3}$", "Ученик добавил третий исход — падение на ребро, который не учитывается.")], lambda: R(1, 2) == R(1, 2), vals=[R(1, 2), 1, 0, R(1, 3)])
T("G9_S35_02", "B", "exact_number", r"Монету бросают два раза. Какова вероятность того, что оба раза выпадет «орёл»?", r"$\dfrac{1}{4}$",
  [(r"$\dfrac{1}{2}$", "Ученик не учёл, что броска два, и взял вероятность одного броска."),
   (r"$\dfrac{1}{3}$", "Ученик считал равновозможными исходы «два орла», «один орёл», «ни одного», а исход «один орёл» дважды вероятнее."),
   (r"$1$", "Ученик сложил вероятности двух бросков.")],
  lambda: R(sum(1 for p in product("ОР", repeat=2) if p == ("О", "О")), 4) == R(1, 4), vals=[R(1, 4), R(1, 2), R(1, 3), 1])
# S35_03 чётное на кубике
T("G9_S35_03", "A", "exact_number", r"Найдите вероятность выпадения чётного числа очков при одном бросании игрального кубика.", r"$\dfrac{1}{2}$",
  [(r"$\dfrac{1}{3}$", "Ученик насчитал только два чётных числа (2 и 4), пропустив 6."), (r"$\dfrac{1}{6}$", "Ученик взял вероятность одного исхода."),
   (r"$\dfrac{2}{3}$", "Ученик ошибся в подсчёте благоприятных исходов: насчитал 4 вместо 3.")],
  lambda: R(len([v for v in range(1, 7) if v % 2 == 0]), 6) == R(1, 2), vals=[R(1, 2), R(1, 3), R(1, 6), R(2, 3)])
# S36_02 частота и вероятность
T("G9_S36_02", "B", "text", r"Монету бросили $100$ раз, «орёл» выпал $47$ раз. Чему равны относительная частота выпадения «орла» и вероятность выпадения «орла»?",
  r"частота $0{,}47$, вероятность $0{,}5$", [(r"частота $0{,}5$, вероятность $0{,}47$", "Ученик перепутал относительную частоту с вероятностью."),
                                           (r"частота и вероятность равны $0{,}47$", "Ученик считал вероятность равной частоте, полученной в опыте."),
                                           (r"частота $47$, вероятность $0{,}5$", "Ученик указал число появлений события вместо относительной частоты.")],
  lambda: R(47, 100) == R(47, 100))
T("G9_S36_02", "A", "text", r"Какое утверждение верно?", "при увеличении числа опытов относительная частота события обычно приближается к его вероятности",
  [("относительная частота события всегда равна его вероятности", "Ученик не учёл, что частота зависит от результатов конкретной серии опытов."),
   ("вероятность события зависит от числа проведённых опытов", "Ученик перепутал вероятность (число, не зависящее от опытов) с относительной частотой."),
   ("относительная частота события не может быть равна нулю", "Ученик не учёл, что в серии опытов событие может ни разу не произойти.")], lambda: True)
# S36_03 таблица эксперимента
T("G9_S36_03", "A", "exact_number", r"В серии из $100$ бросаний игрального кубика «шестёрка» выпала $18$ раз. Найдите относительную частоту выпадения «шестёрки».", r"$0{,}18$",
  [(r"$18$", "Ученик указал число появлений события, не разделив его на число опытов."), (r"$\dfrac{1}{6}$", "Ученик указал вероятность, а не относительную частоту."),
   (r"$0{,}82$", "Ученик нашёл частоту противоположного события.")], lambda: R(18, 100) == R(18, 100), vals=[R(18, 100), 18, R(1, 6), R(82, 100)])
T("G9_S36_03", "B", "exact_number", r"Стрелок сделал $50$ выстрелов и попал в мишень $42$ раза. Найдите относительную частоту промахов.", r"$0{,}16$",
  [(r"$0{,}84$", "Ученик нашёл относительную частоту попаданий, а не промахов."), (r"$8$", "Ученик указал число промахов, не разделив его на число выстрелов."),
   (r"$0{,}08$", "Ученик разделил число промахов на 100 вместо 50.")], lambda: R(50 - 42, 50) == R(16, 100))
# S37_05 интерпретация случайной величины
T("G9_S37_05", "A", "text", r"Случайная величина $X$ — число очков, выпавших при одном бросании игрального кубика. Какие значения может принимать $X$?",
  r"$1$, $2$, $3$, $4$, $5$, $6$", [(r"$0$, $1$, $2$, $3$, $4$, $5$, $6$", "Ученик добавил значение 0, которого на кубике нет."),
                                   (r"$1$, $2$, $3$, $4$, $5$", "Ученик пропустил значение 6."), (r"только $6$", "Ученик указал только наибольшее значение.")], lambda: True)
T("G9_S37_05", "B", "text", r"Монету бросают $3$ раза. Случайная величина $X$ — число выпавших «орлов». Какие значения может принимать $X$?",
  r"$0$, $1$, $2$, $3$", [(r"$1$, $2$, $3$", "Ученик забыл, что «орёл» может не выпасть ни разу."), (r"$0$, $1$, $2$", "Ученик не учёл, что «орёл» может выпасть все три раза."),
                          (r"от $0$ до $8$", "Ученик перепутал значения величины с числом исходов опыта (2³ = 8).")],
  lambda: {p.count("О") for p in product("ОР", repeat=3)} == {0, 1, 2, 3})
T("G9_S37_05", "C", "exact_number", r"Бросают два игральных кубика. Случайная величина $X$ — сумма выпавших очков. Сколько различных значений может принимать $X$?", r"$11$",
  [(r"$12$", "Ученик считал, что сумма может принимать значения от 1 до 12."), (r"$36$", "Ученик перепутал число значений величины с числом исходов опыта."),
   (r"$6$", "Ученик указал число граней одного кубика.")], lambda: len({p + q for p in range(1, 7) for q in range(1, 7)}) == 11)
# S38_02 размах
T("G9_S38_02", "A", "exact_number", r"Найдите размах ряда данных: $3$, $7$, $2$, $9$, $5$.", r"$7$",
  [(r"$6$", "Ученик взял за наименьшее значение первое число ряда (3), а не 2."), (r"$26$", "Ученик нашёл сумму чисел ряда."),
   (r"$5$", "Ученик нашёл медиану вместо размаха.")], lambda: max([3, 7, 2, 9, 5]) - min([3, 7, 2, 9, 5]) == 7)
